\title{The Arithmetic Residue of $E_4^2 = E_8$: \\ Sharp Divisor-Sum Congruences from Pointwise Power Residues}
\author{Aristotle}
\date{July 14, 2026}

\begin{document}

\begin{abstract}
The one-dimensionality of the space of weight-$8$ level-one modular forms forces the Eisenstein identity
$E_4^2 = E_8$. Comparing the $q$-expansions of the two sides yields the exact convolution law
$\sigma_7(n) = \sigma_3(n) + 120\sum_{i=1}^{n-1}\sigma_3(i)\sigma_3(n-i)$, and in particular the divisor-sum
congruence $\sigma_7(n)\equiv\sigma_3(n)\pmod{120}$. We isolate the arithmetic content of this transcendental
identity and prove it by wholly elementary means. The central tool is a \emph{transfer principle}: any
pointwise power congruence $m\mid a^j-a^k$ holding for all integers $a$ propagates verbatim to the divisor
power sums, $m\mid\sigma_j(n)-\sigma_k(n)$, because a divisor sum is a sum of powers. Combining this with the
finite residue computations $120\mid d^7-d^3$ and $24\mid d^5-d^3$ we obtain the congruences
$\sigma_7\equiv\sigma_3\pmod{120}$ and $\sigma_5\equiv\sigma_3\pmod{24}$. We further prove that both moduli are
\emph{optimal}: $120$ (resp.\ $24$) is the greatest modulus for which the congruence holds for all $n$, each
sharpness statement witnessed at $n=2$. Scaling by the $E_8$ vector-count normalization $240$ gives
$28800\mid 240\sigma_7(n)-240\sigma_3(n)$, the modulus relevant to the rank-$16$ even unimodular lattice genus.
Finally, we verify concrete instances of the exact convolution law, confirming that the elementary arithmetic
reproduces the Eisenstein coefficients term by term.
\end{abstract}

\maketitle

\section{Introduction}

For a nonnegative integer $k$ and a positive integer $n$, the \emph{divisor power sum} is
\[
  \sigma_k(n) = \sum_{d\mid n} d^k,
\]
the sum of the $k$-th powers of the positive divisors of $n$. These arithmetic functions are the building
blocks of the Fourier ($q$-expansion) coefficients of Eisenstein series. In particular,
\[
  E_4 = 1 + 240\sum_{n\ge 1}\sigma_3(n)q^n, \qquad E_8 = 1 + 480\sum_{n\ge 1}\sigma_7(n)q^n.
\]
The space $M_8$ of holomorphic level-one modular forms of weight $8$ is one-dimensional. Since $E_4^2$ and
$E_8$ are both weight-$8$ forms with constant term $1$, they coincide:
\begin{equation}\label{eq:E4E8}
  E_4^2 = E_8.
\end{equation}
Extracting the coefficient of $q^n$ from \eqref{eq:E4E8} gives, after dividing by $480$, the \emph{exact
convolution law}
\begin{equation}\label{eq:conv}
  \sigma_7(n) = \sigma_3(n) + 120\sum_{i=1}^{n-1}\sigma_3(i)\,\sigma_3(n-i).
\end{equation}
The self-convolution term is a nonnegative integer, so \eqref{eq:conv} immediately implies
\begin{equation}\label{eq:cong}
  \sigma_7(n)\equiv\sigma_3(n)\pmod{120}\qquad\text{for all } n\ge 1.
\end{equation}
This paper isolates \eqref{eq:cong}---together with its sharpness, its weight-$6$ analogue, and a
lattice-theoretic corollary---as a self-contained, elementary theory. The identity \eqref{eq:E4E8} serves only
as motivation.

\section{Pointwise power-residue laws}

We work over $\Z$ throughout, writing $\sigma_k(n) = \sum_{d\mid n} d^k \in \Z$.

\begin{lemma}[Residue-to-divisibility bridge]\label{lem:bridge}
Let $m,j,k$ be nonnegative integers and suppose $x^j = x^k$ for every $x\in\Z/m\Z$. Then $m\mid a^j-a^k$ for
every integer $a$.
\end{lemma}

\begin{proof}
The reduction map $\Z\to\Z/m\Z$ is a ring homomorphism, so the image of $a^j-a^k$ is
$\bar a^{\,j}-\bar a^{\,k}$. By hypothesis this is $0$, which is equivalent to $m\mid a^j-a^k$.
\end{proof}

\begin{theorem}[Pointwise power residues]\label{thm:pointwise}
For every integer $d$,
\[
  120\mid d^7-d^3 \qquad\text{and}\qquad 24\mid d^5-d^3.
\]
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:bridge} it suffices to verify $x^7=x^3$ for all $x\in\Z/120\Z$ and $x^5=x^3$ for all
$x\in\Z/24\Z$; both are finite checks. Conceptually, factor $d^7-d^3 = d^3(d-1)(d+1)(d^2+1)$ and use
$120 = 8\cdot 3\cdot 5$: divisibility by $8$ (case split on parity of $d$), by $3$ (one of $d-1,d,d+1$ is a
multiple of $3$), and by $5$ (Fermat: $d^7 = d^5 d^2 \equiv d^3\pmod 5$). The claim $24\mid d^5-d^3$ follows
analogously from $24=8\cdot 3$ and $d^5-d^3=d^3(d-1)(d+1)$.
\end{proof}

\section{The transfer principle and the divisor-sum congruences}

\begin{theorem}[Transfer principle]\label{thm:transfer}
Let $m\in\Z$ and $j,k$ be nonnegative integers with $m\mid a^j-a^k$ for every integer $a$. Then for every
positive integer $n$,
\[
  m\mid\sigma_j(n)-\sigma_k(n).
\]
\end{theorem}

\begin{proof}
Combining the two sums,
\[
  \sigma_j(n)-\sigma_k(n) = \sum_{d\mid n} d^j - \sum_{d\mid n} d^k = \sum_{d\mid n}\bigl(d^j-d^k\bigr).
\]
Each summand is divisible by $m$, hence so is the total.
\end{proof}

\begin{theorem}[Divisor-sum congruences]\label{thm:cong}
For every positive integer $n$,
\[
  \sigma_7(n)\equiv\sigma_3(n)\pmod{120}\qquad\text{and}\qquad \sigma_5(n)\equiv\sigma_3(n)\pmod{24}.
\]
\end{theorem}

\begin{proof}
Combine Theorem~\ref{thm:pointwise} with Theorem~\ref{thm:transfer} for $(j,k,m)=(7,3,120)$ and $(5,3,24)$.
\end{proof}

\section{Sharpness of the moduli}

For fixed exponents $j,k$, set $\mathcal{M}_{j,k} = \{\, m\in\Z_{>0} : m\mid\sigma_j(n)-\sigma_k(n)\ \forall n\,\}$.

\begin{theorem}[Optimality]\label{thm:sharp}
The number $120$ is the greatest element of $\mathcal{M}_{7,3}$, and $24$ is the greatest element of
$\mathcal{M}_{5,3}$. The analogous statements hold for the pointwise admissible sets, with greatest elements
$120$ and $24$.
\end{theorem}

\begin{proof}
Membership is Theorem~\ref{thm:cong}. For the upper bound, evaluate at $n=2$, with divisors $1,2$:
\[
  \sigma_3(2)=9,\quad \sigma_7(2)=129,\quad \sigma_5(2)=33,
\]
so $\sigma_7(2)-\sigma_3(2)=120$ and $\sigma_5(2)-\sigma_3(2)=24$. Any $m\in\mathcal{M}_{7,3}$ divides the
value at $n=2$, hence $m\mid 120$ and $m\le 120$; and $120$ is attained. Similarly every
$m\in\mathcal{M}_{5,3}$ satisfies $m\mid 24$, so $m\le 24$, attained at $24$. The pointwise statements are
witnessed at $a=2$, where $a^7-a^3=120$ and $a^5-a^3=24$.
\end{proof}

\section{A cross-domain corollary: the rank-16 even unimodular genus}

There are exactly two even unimodular lattices of rank $16$: $E_8\oplus E_8$ and $D_{16}^+$. Their theta
series are weight-$8$ modular forms, and the number of vectors of squared length $2n$ has the shape
$240\,\sigma_7(n)$ plus a cusp-form contribution. The relevant comparison modulus is $28800 = 240\cdot 120$.

\begin{theorem}[$E_8$-normalized congruence]\label{thm:e8}
For every positive integer $n$,
\[
  28800\mid 240\,\sigma_7(n)-240\,\sigma_3(n).
\]
\end{theorem}

\begin{proof}
By Theorem~\ref{thm:cong}, $\sigma_7(n)-\sigma_3(n)=120c$ for some integer $c$. Then
$240\sigma_7(n)-240\sigma_3(n)=240\cdot 120\,c=28800\,c$.
\end{proof}

\section{The exact convolution law}

Define $(\sigma_3\star\sigma_3)(n) = \sum_{i=1}^{n-1}\sigma_3(i)\sigma_3(n-i)$, an empty sum ($=0$) at $n=1$.

\begin{theorem}[Convolution-law instances]\label{thm:convinst}
The identity $\sigma_7(n) = \sigma_3(n) + 120(\sigma_3\star\sigma_3)(n)$ holds for $n=2,3,4,5$.
\end{theorem}

\begin{proof}
Direct computation. At $n=4$: $\sigma_3(4)=73$, $\sigma_7(4)=16513$, and
$(\sigma_3\star\sigma_3)(4)=28+81+28=137$, whence $73+120\cdot 137=16513$. The cases $n=2,3,5$ are analogous.
\end{proof}

