from typing import List

def divisors(n: int) -> List[int]:
    """Sorted positive divisors of n."""
    ds: List[int] = []
    d = 1
    while d * d <= n:
        if n % d == 0:
            ds.append(d)
            if d != n // d:
                ds.append(n // d)
        d += 1
    return sorted(ds)

def sigma(k: int, n: int) -> int:
    """Divisor power sum sigma_k(n) = sum_{d|n} d^k."""
    return sum(d ** k for d in divisors(n))

def check_congruence(limit: int = 30) -> bool:
    """Verify sigma_7(n) = sigma_3(n) (mod 120) for n = 1..limit."""
    for n in range(1, limit + 1):
        if (sigma(7, n) - sigma(3, n)) % 120 != 0:
            return False
    return True

if __name__ == "__main__":
    for n in range(1, 13):
        s3, s7 = sigma(3, n), sigma(7, n)
        print(f"n={n:2d}  sigma_3={s3:6d}  sigma_7={s7:12d}  (s7-s3)/120={(s7-s3)//120}")
    print("Congruence holds up to n=30:", check_congruence())

