def conv_sigma3(n: int) -> int:
    """Self-convolution (sigma_3 * sigma_3)(n) = sum_{i=1}^{n-1} sigma_3(i) sigma_3(n-i)."""
    return sum(sigma(3, i) * sigma(3, n - i) for i in range(1, n))

def verify_exact_law(limit: int = 15) -> bool:
    """sigma_7(n) = sigma_3(n) + 120 * (sigma_3 * sigma_3)(n) for all n <= limit."""
    return all(sigma(7, n) == sigma(3, n) + 120 * conv_sigma3(n)
               for n in range(1, limit + 1))

if __name__ == "__main__":
    for n in range(1, 12):
        pred = sigma(3, n) + 120 * conv_sigma3(n)
        print(f"n={n:2d}  predicted={pred:12d}  sigma_7={sigma(7,n):12d}  ok={pred==sigma(7,n)}")
    print("Exact convolution law holds up to n=15:", verify_exact_law())

