    # Step 1: certify the pointwise law over Z/mZ (finite check)
    for x in 0 .. m-1:
        if (x^j - x^k) mod m != 0:
            return FAIL   # pointwise law does not hold for this m
    # Step 2: transfer to the divisor sum for the target n
    total = 0
    for d in divisors(n):
        total = total + (d^j - d^k)
    assert total mod m == 0     # guaranteed by Step 1
    return total // m           # the certified quotient

